-- REFERENCE OUTLINE ONLY.
create table if not exists creator_interop_budgets (id uuid primary key default gen_random_uuid(), organization_id uuid not null, period_start date not null, period_end date not null, currency text not null, approved_minor bigint not null, status text not null, decision_id uuid, created_at timestamptz not null default now());
create table if not exists creator_interop_contributions (id uuid primary key default gen_random_uuid(), budget_id uuid not null, participant_external_ref text, contribution_type text not null, assessed_minor bigint, received_minor bigint not null default 0, restrictions jsonb not null default '{}', conflict_review_status text not null, created_at timestamptz not null default now());
create table if not exists creator_interop_oversight_cases (id uuid primary key default gen_random_uuid(), organization_id uuid not null, function_type text not null, case_type text not null, status text not null, restricted_payload jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists creator_interop_relationship_agreements (id uuid primary key default gen_random_uuid(), organization_id uuid not null, counterparty_ref text not null, relationship_type text not null, scope jsonb not null, status text not null, effective_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now());
